function openDB(){return new Promise(resolve=>{if(!('indexedDB'in window)){resolve(null);return}try{const req=indexedDB.open('hanami-data-v1',1);req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains('jlpt'))req.result.createObjectStore('jlpt')};req.onsuccess=()=>resolve(req.result);req.onerror=()=>resolve(null)}catch{resolve(null)}})}
