evidence=window.createHanamiEvidence({state,save,render,esc,attr,data,ready:l=>TYPES.every(t=>loadState[`ready-${t}-${l}`]),speak,toast});window.HANAMI_NATIVE=evidence;evidence.init();
coverage=window.createHanamiN5N4Coverage({state,save,addXP,addDaily,speak,esc,attr,render,toast,setPage,data,ready:l=>TYPES.every(t=>loadState[`ready-${t}-${l}`])});
foundations=window.createHanamiFoundations({state,save,addXP,addDaily,speak,esc,attr,render,toast,setPage,data,goKana:()=>{guided.showKana();setPage('academy')},fullLevelReady:l=>TYPES.every(t=>loadState[`ready-${t}-${l}`])});
